    ["{name} is no longer nearby."] = "Уже не поруч: {name}.",
    ["{name} · game voice"] = "{name} · голос із гри",
    ["Play"] = "Відтворити",
    ["Plays one of this character’s own lines from the game, through the game’s normal dialogue audio, so you can compare their companion voice with it. You hear it when you return to gameplay; each press tries another line, and a character may have no line for some of them."] = "Відтворює одну з власних реплік цього персонажа з гри через звичайний звук діалогів гри, щоб порівняти з нею його голос супутника. Ти почуєш її, коли повернешся до гри; кожне натискання пробує іншу репліку, і для деяких у персонажа може не бути репліки.",
    ["{name} will say one of their game lines when you return to the game."] = "Скаже одну зі своїх реплік із гри, коли ти повернешся до гри: {name}.",
    ["Lip sync delay (Bluetooth)"] = "Затримка синхронізації губ (Bluetooth)",
    ["Bluetooth earbuds and headphones play sound a little later than the picture, so lips and subtitles can run slightly ahead of the voice. This holds them back to match, for every voice. Auto uses 150 ms while Windows plays through a Bluetooth device and none otherwise; choose a value if your headset is faster or slower. The game’s own dialogue has the same Bluetooth delay and does not correct it."] = "Bluetooth-навушники відтворюють звук трохи пізніше за картинку, тож губи й субтитри можуть трохи випереджати голос. Цей параметр затримує їх, щоб збігалося, для всіх голосів. Авто використовує 150 мс, поки Windows відтворює через Bluetooth-пристрій, інакше без затримки; вибери значення, якщо твоя гарнітура швидша чи повільніша. Власні діалоги гри мають таку саму затримку Bluetooth, і гра її не виправляє.",
    ["Choose one of the listed lip sync delays."] = "Вибери одну з наведених затримок синхронізації губ.",
    ["Behavior: {list}"] = "Поведінка: {list}",
    ["In your party: {count}"] = "У вашій групі: {count}",
    ["Memory: remembers your conversations"] = "Пам’ять: пам’ятає ваші розмови",
    ["Multilingual: replies in your language"] = "Багатомовність: відповідає вашою мовою",
    ["Relationship: {mode}"] = "Стосунки: {mode}",
    ["Speech: {list}"] = "Мовлення: {list}",
    ["Added"] = "Додано",
    ["Added (ends in {tail})"] = "Додано (закінчується на {tail})",
    ["Checking…"] = "Перевірка…",
    ["Convai API key"] = "API-ключ Convai",
    ["Convai did not accept that key."] = "Convai не прийняв цей ключ.",
    ["Convai did not accept your API key. Check it in Settings > Development."] = "Convai не прийняв твій API-ключ. Перевір його в меню Налаштування > Розробка.",
    ["Conversations use"] = "Розмови використовують",
    ["You’ve reached today’s free conversation limit. Convai (better quality responses) is back tomorrow. To keep talking now, add a free Mistral key and set Conversation provider to Mistral in Settings > Development. A fully local option is coming."] = "Ти вичерпав сьогоднішній безкоштовний ліміт розмов. Convai (краща якість відповідей) повернеться завтра. Щоб продовжити зараз, додай безкоштовний ключ Mistral і в меню Налаштування > Розробка встанови Постачальника розмов: Mistral. Незабаром з'явиться і повністю локальний варіант.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Development."] = "Досягнуто ліміт розмов. Спробуй пізніше або додай безкоштовний ключ Mistral і в меню Налаштування > Розробка встанови Постачальника розмов: Mistral.",
    ["Mistral’s free limit is reached for now. Try again in a moment."] = "Безкоштовний ліміт Mistral поки що досягнуто. Спробуй ще раз за мить.",
    ["Use a Convai API key of your own for conversations. Paste it below, turn this on and choose Apply. The change waits until no conversation is running."] = "Для розмов використовуй власний API-ключ Convai. Встав його нижче, увімкни цю опцію і вибери «Застосувати». Зміна чекатиме, поки жодна розмова не триває.",
    ["Copy your key first. It is read from the clipboard once, checked with Convai and saved on this computer."] = "Спочатку скопіюй ключ. Його один раз зчитують з буфера обміну, перевіряють у Convai і зберігають на цьому комп'ютері.",
    ["Deletes the saved key. Conversations go back to the shared plan."] = "Видаляє збережений ключ. Розмови повертаються до спільного тарифу.",
    ["Not added"] = "Не додано",
    ["Paste Convai API key"] = "Вставити API-ключ Convai",
    ["Paste from clipboard"] = "Вставити з буфера обміну",
    ["Remove"] = "Видалити",
    ["Remove my Convai API key"] = "Видалити мій API-ключ Convai",
    ["Saved on this computer only. Only the last four characters are ever shown."] = "Зберігається лише на цьому комп’ютері. Показуються лише останні чотири символи.",
    ["Shared plan: daily limit reached"] = "Спільний тариф: денний ліміт вичерпано",
    ["Shared plan: limit used up"] = "Спільний тариф: ліміт вичерпано",
    ["The clipboard could not be read."] = "Не вдалося прочитати буфер обміну.",
    ["The clipboard does not hold a Convai API key."] = "У буфері обміну немає API-ключа Convai.",
    ["The clipboard is empty. Copy your key first."] = "Буфер обміну порожній. Спершу скопіюй ключ.",
    ["The key could not be saved."] = "Не вдалося зберегти ключ.",
    ["The request could not be sent. Try again."] = "Не вдалося надіслати запит. Спробуй ще раз.",
    ["The shared plan"] = "Спільний тариф",
    ["The shared plan: {left} of {limit} left today"] = "Спільний тариф: сьогодні залишилось {left} з {limit}",
    ["Use my own Convai API key"] = "Використовувати мій API-ключ Convai",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Development."] = "Твій API-ключ Convai досяг ліміту тарифу. Спробуй пізніше або додай інший ключ у меню Налаштування > Розробка.",
    ["Your key was removed."] = "Твій ключ видалено.",
    ["Your key: not accepted"] = "Твій ключ: не прийнято",
    ["Your key: plan limit reached"] = "Твій ключ: досягнуто ліміт тарифу",
    ["Your own key"] = "Твій ключ",
    ["Your Convai plan cannot hold the memory these conversations need. Free a memory user in your Convai account or use another key."] = "Твій тариф Convai не може вмістити пам'ять, яка потрібна цим розмовам. Звільни одного користувача пам'яті в обліковому записі Convai або використай інший ключ.",
    ["Your Convai plan has no room for conversation memory, so companions will not remember past talks."] = "У твоєму тарифі Convai немає місця для пам'яті розмов, тож супутники не пам'ятатимуть попередні бесіди.",
    ["Your key: no room for memory"] = "Твій ключ: немає місця для пам'яті",
    ["Your own key, without memory"] = "Твій ключ, без пам'яті",
    ["Choose one of the listed conversation providers."] = "Обери одного з наведених постачальників розмов.",
    ["Convai free tier"] = "Convai (безкоштовний тариф)",
    ["Convai: Mistral has no key yet"] = "Convai: для Mistral ще немає ключа",
    ["Conversation provider"] = "Постачальник розмов",
    ["Copy your free key from Mistral first. It is read from the clipboard once, checked with Mistral and saved on this computer. You can also save it in the file player-mistral-key.txt in the conversation service folder."] = "Спершу скопіюй свій безкоштовний ключ із Mistral. Його один раз зчитують із буфера обміну, перевіряють у Mistral і зберігають на цьому комп’ютері. Також можна зберегти його у файлі player-mistral-key.txt у папці служби розмов.",
    ["Deletes the saved key. Conversations go back to Convai free tier."] = "Видаляє збережений ключ. Розмови знову працюють через Convai (безкоштовний тариф).",
    ["Mistral (free plan)"] = "Mistral (безкоштовний тариф)",
    ["Mistral did not accept that key."] = "Mistral не прийняв цей ключ.",
    ["Mistral did not accept your key. Check it in Settings > Development."] = "Mistral не прийняв твій ключ. Перевір його в меню Налаштування > Розробка.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Development."] = "Для Mistral ще немає ключа, тож використовується Convai. Додай свій ключ у меню Налаштування > Розробка.",
    ["Mistral key"] = "Ключ Mistral",
    ["Mistral replies are spoken by a local voice instead of the Convai cloud voice."] = "Відповіді Mistral озвучує локальний голос, а не хмарний голос Convai.",
    ["Mistral: free limit reached for now"] = "Mistral: безкоштовний ліміт поки що досягнуто",
    ["Mistral: key not accepted"] = "Mistral: ключ не прийнято",
    ["Mistral: model unavailable"] = "Mistral: модель недоступна",
    ["Paste Mistral key"] = "Вставити ключ Mistral",
    ["Remove my Mistral key"] = "Видалити мій ключ Mistral",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Development, or type your message."] = "Розмова з компаньйонами поки що потребує Convai. Встанови для параметра Постачальник розмов значення Convai (безкоштовний тариф) в меню Налаштування > Розробка або напиши повідомлення.",
    ["The Mistral model is unavailable right now. Try again in a minute."] = "Модель Mistral зараз недоступна. Спробуй ще раз за хвилину.",
    ["Waiting for the conversation to end"] = "Очікування завершення розмови",
    ["Which provider answers your conversations right now and, for Convai, which plan pays for them. Changes wait until no conversation is running."] = "Який постачальник зараз відповідає у твоїх розмовах і, для Convai, який тариф за них платить. Зміни чекають, поки жодна розмова не триває.",
    ["Who writes your companions’ replies. Convai is the default. It works with no setup and gives better quality responses. Mistral uses its free plan with your own free key (add it below; signing up needs phone verification): memory stays on this computer, and the free plan allows about one message a second and a monthly allowance. A Convai cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works. The change waits until no conversation is running; choose Apply."] = "Хто пише відповіді твоїх компаньйонів. Convai — типовий варіант. Працює без налаштування й дає якісніші відповіді. Mistral використовує свій безкоштовний тариф із твоїм власним безкоштовним ключем (додай його нижче; для реєстрації потрібна перевірка телефону): пам’ять залишається на цьому комп’ютері, а безкоштовний тариф дозволяє приблизно одне повідомлення на секунду та місячний ліміт. Хмарний голос Convai замінюється локальним голосом. Розпізнавання мови відбувається на цьому комп’ютері, тому голосова клавіша працює. Зміна чекає, поки жодна розмова не триває; вибери «Застосувати».",
    ["Who writes your companions’ replies. Convai is the default. It works with no setup and gives better quality responses. Mistral uses its free plan with your own free key (add it below; signing up needs phone verification): memory stays on this computer, and the free plan allows about one message a second and a monthly allowance. A Convai cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with Mistral, so type your messages. The change waits until no conversation is running; choose Apply."] = "Хто пише відповіді твоїх компаньйонів. Convai — типовий варіант. Працює без налаштування й дає якісніші відповіді. Mistral використовує свій безкоштовний тариф із твоїм власним безкоштовним ключем (додай його нижче; для реєстрації потрібна перевірка телефону): пам’ять залишається на цьому комп’ютері, а безкоштовний тариф дозволяє приблизно одне повідомлення на секунду та місячний ліміт. Хмарний голос Convai замінюється локальним голосом. Розпізнавання мови для голосової клавіші з Mistral поки що недоступне, тож вводь повідомлення. Зміна чекає, поки жодна розмова не триває; вибери «Застосувати».",
    ["Convai: Groq has no key yet"] = "Convai: для Groq ще немає ключа",
    ["Convai: Local AI is not ready"] = "Convai: локальний ШІ не готовий",
    ["Copy your free key from Groq first. It is read from the clipboard once, checked with Groq and saved on this computer. You can also save it in the file player-groq-key.txt in the conversation service folder."] = "Спочатку скопіюй свій безкоштовний ключ із Groq. Його один раз зчитують із буфера обміну, перевіряють у Groq і зберігають на цьому комп'ютері. Також можна зберегти його у файлі player-groq-key.txt у папці служби розмов.",
    ["Deletes the saved key. Conversations go back to Mistral if you added a key there, otherwise to Convai free tier."] = "Видаляє збережений ключ. Розмови повернуться до Mistral, якщо ти додав ключ там, інакше до Convai (безкоштовний тариф).",
    ["Groq (free plan)"] = "Groq (безкоштовний тариф)",
    ["Groq did not accept that key."] = "Groq не прийняв цей ключ.",
